<?php
/**
 * AI Care Coordinator theme functions.
 */
if (!defined('ABSPATH')) exit;

// Version comes from style.css so one bump there drives cache-busting, reinstall and Git Updater.
define('AICC_VER', wp_get_theme(get_template())->get('Version') ?: '1.3.5');
define('AICC_NAME', 'AI Care Coordinator');

require_once get_template_directory() . '/inc/pages.php';
require_once get_template_directory() . '/inc/seo.php';
require_once get_template_directory() . '/inc/forms.php';
require_once get_template_directory() . '/inc/shortcodes.php';
require_once get_template_directory() . '/inc/setup.php';
require_once get_template_directory() . '/inc/tracking.php';

add_action('after_setup_theme', function () {
    add_theme_support('title-tag');
    add_theme_support('post-thumbnails');
    add_theme_support('html5', ['search-form', 'gallery', 'caption', 'style', 'script']);
    add_theme_support('responsive-embeds');
    register_nav_menus(['primary' => 'Primary']);
});

add_action('wp_enqueue_scripts', function () {
    $u = get_template_directory_uri();
    wp_enqueue_style('aicc-fonts', 'https://fonts.googleapis.com/css2?family=Geist:wght@300;400;500;600&display=swap', [], null);
    wp_enqueue_style('aicc', $u . '/assets/css/site.css', [], AICC_VER);
    wp_enqueue_script('aicc', $u . '/assets/js/site.js', [], AICC_VER, true);
    wp_localize_script('aicc', 'AICC', ['audio' => $u . '/assets/audio/sample-check-in-call.mp3']);
    // Not needed on this site.
    wp_dequeue_style('wp-block-library');
    wp_dequeue_style('global-styles');
    wp_dequeue_style('classic-theme-styles');
}, 20);

add_filter('wp_resource_hints', function ($hints, $type) {
    if ($type === 'preconnect') {
        $hints[] = ['href' => 'https://fonts.gstatic.com', 'crossorigin'];
        $hints[] = 'https://fonts.googleapis.com';
    }
    return $hints;
}, 10, 2);

// Speed and cleanup.
remove_action('wp_head', 'print_emoji_detection_script', 7);
remove_action('wp_print_styles', 'print_emoji_styles');
remove_action('wp_head', 'wp_generator');
remove_action('wp_head', 'wlwmanifest_link');
remove_action('wp_head', 'rsd_link');
remove_action('wp_head', 'wp_shortlink_wp_head');
add_filter('the_generator', '__return_empty_string');

// Keep page content HTML intact (wpautop would break the layout blocks).
add_action('init', function () {
    remove_filter('the_content', 'wpautop');
    remove_filter('the_excerpt', 'wpautop');
});
add_filter('the_content', function ($c) {
    if (is_singular('post')) return wpautop($c);
    return $c;
}, 9);

/** Small SVG icons. */
function aicc_icon($name) {
    $i = [
        'arrow' => '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 8h10M9 4l4 4-4 4"/></svg>',
        'play'  => '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5.5v13l11-6.5z"/></svg>',
        'pause' => '<svg viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="5" width="4" height="14" rx="1"/><rect x="14" y="5" width="4" height="14" rx="1"/></svg>',
        'check' => '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3.5 8.5l3 3 6-7"/></svg>',
    ];
    return $i[$name] ?? '';
}

