/** Permalink for a page by slug, with fallback. */
function aicc_url($slug) {
    if ($slug === '' || $slug === 'home') return home_url('/');
    $p = get_page_by_path($slug);
    return $p ? get_permalink($p) : home_url('/' . trim($slug, '/') . '/');
}
